using System;
using System.Diagnostics;
using System.Threading.Tasks;

// PROGRAM: Mengamati Penalti Latensi TCP Handshake Awal vs Connection Reuse (Keep-Alive)
public class NetworkSimulator
{
    public static async Task<long> RequestWithColdConnectionAsync()
    {
        var sw = Stopwatch.StartNew();
        // 1. DNS Resolution (~15ms)
        await Task.Delay(15);
        // 2. TCP 3-Way Handshake SYN, SYN-ACK, ACK (~30ms)
        await Task.Delay(30);
        // 3. TLS 1.3 Key Exchange Handshake (~25ms)
        await Task.Delay(25);
        // 4. HTTP Roundtrip Data Transfer (~10ms)
        await Task.Delay(10);
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }

    public static async Task<long> RequestWithWarmKeepAliveSocketAsync()
    {
        var sw = Stopwatch.StartNew();
        // Socket sudah terbuka (Keep-Alive): Langsung HTTP Data Transfer (~10ms)
        await Task.Delay(10);
        sw.Stop();
        return sw.ElapsedMilliseconds;
    }
}

public class Program
{
    public static async Task Main()
    {
        Console.WriteLine("=== SIMULASI LATENSI NETWORK CONNECTION REUSE ===");

        long coldLatency = await NetworkSimulator.RequestWithColdConnectionAsync();
        Console.WriteLine($"Request 1 (Dingin - Handshake Lengkap): {coldLatency} ms (Status: 200 OK)");

        long warmLatency = await NetworkSimulator.RequestWithWarmKeepAliveSocketAsync();
        Console.WriteLine($"Request 2 (Hangat - TCP Socket Reuse): {warmLatency} ms (Status: 200 OK)");

        Console.WriteLine($"\nEfisiensi Socket Reuse: {coldLatency - warmLatency} ms terpangkas!");
    }
}

