using System;

public class TcpAckCalculator
{
    public static long CalculateNextExpectedAck(long initialSeq, int[] packetPayloadLengths)
    {
        if (packetPayloadLengths == null || packetPayloadLengths.Length == 0)
            return initialSeq;

        long currentSeq = initialSeq;
        foreach (int length in packetPayloadLengths)
        {
            if (length > 0)
            {
                currentSeq += length;
            }
        }

        return currentSeq;
    }

    public static void Main()
    {
        int[] packets = { 100, 200, 300 };
        Console.WriteLine($"Next Ack: {CalculateNextExpectedAck(1000, packets)}");
    }
}
